package main

import (
	"bufio"
	"fmt"
	"os"
)

type Scanner struct {
	reader *bufio.Reader
}

func NewScanner() *Scanner {
	return &Scanner{
		reader: bufio.NewReader(os.Stdin),
	}
}

func (s *Scanner) nextUint64() uint64 {
	var x uint64
	fmt.Fscan(s.reader, &x)
	return x
}

func exec() {
	sc := NewScanner()
	a := sc.nextUint64()
	b := sc.nextUint64()
	var cnt uint64 = 0
	for i := 0; i < 64; i++ {
		k := (uint64(1) << uint(i)) - 1
		for j := 0; j < i-1; j++ {
			aim := k ^ (uint64(1) << uint(j))
			if a <= aim && aim <= b {
				cnt++
			}
		}
	}
	fmt.Println(cnt)
}

func main() {
	exec()
}

