type Scanner struct {
	r   *bufio.Reader
	buf []byte
}

func NewScanner() *Scanner {
	return &Scanner{
		r: bufio.NewReader(os.Stdin),
	}
}

func (s *Scanner) next() string {
	for {
		if len(s.buf) > 0 {
			i := 0
			for i < len(s.buf) && s.buf[i] == ' ' {
				i++
			}
			if i == len(s.buf) {
				s.buf = nil
				continue
			}
			j := i
			for j < len(s.buf) && s.buf[j] != ' ' {
				j++
			}
			token := string(s.buf[i:j])
			if j == len(s.buf) {
				s.buf = nil
			} else {
				s.buf = s.buf[j:]
			}
			return token
		}
		line, err := s.r.ReadBytes('\n')
		if err != nil && len(line) == 0 {
			return ""
		}
		s.buf = line
	}
}

