func (s *Scanner) next() string {
	for {
		if s.buf == nil || s.pos >= len(s.buf) {
			line, err := s.r.ReadBytes('\n')
			if err != nil && len(line) == 0 {
				return ""
			}
			s.buf = line
			s.pos = 0
		}
		for s.pos < len(s.buf) && (s.buf[s.pos] == ' ' || s.buf[s.pos] == '\n' || s.buf[s.pos] == '\r' || s.buf[s.pos] == '\t') {
			s.pos++
		}
		if s.pos >= len(s.buf) {
			continue
		}
		start := s.pos
		for s.pos < len(s.buf) && s.buf[s.pos] != ' ' && s.buf[s.pos] != '\n' && s.buf[s.pos] != '\r' && s.buf[s.pos] != '\t' {
			s.pos++
		}
		return string(s.buf[start:s.pos])
	}
}

